use super::*;
use crate::dedup_app::Plan;
use std::{fs::File,io::Read,path::PathBuf,sync::Arc,time::Instant};

pub(crate) struct Working {
    pub staged:[Option<PathBuf>;4],
    scratch:Vec<u8>,
    pub metrics:Metrics,
    execution:Arc<crate::native_execution::Execution>,
    _ticket:crate::native_execution::FeatureTicket,
}
impl Working {
 pub(crate) fn new(plan:&Plan,directory:&PathBuf,e:&Arc<crate::native_execution::Execution>,provided:Option<&crate::native_io::OwnedIo>)->Result<Self,String>{
    let paths=plan.channels.len().checked_mul(directory.capacity().checked_add(128).and_then(|n|n.checked_mul(6)).ok_or("header path overflow")?).ok_or("header path overflow")?;
    if plan.channels.len()>4{return Err("invalid Dedup channel declaration".into());}
    use std::os::unix::ffi::OsStrExt;
    let conversions=plan.channels.iter().try_fold(0usize,|n,ch|{let declared=plan.spec.outputs.iter().find(|d|d.channel==ch.io)?;let owned=provided.is_some_and(|io|io.owned_output_key(&ch.io).is_some())||matches!(declared.location,crate::job_api::Location::Handle(_));if owned{Some(n)}else{ch.path.as_os_str().as_bytes().len().checked_add(directory.capacity()+130).and_then(|v|v.checked_mul(4)).and_then(|v|n.checked_add(v))}}).ok_or("header IO conversion overflow")?;
    let fixed=std::mem::size_of::<Self>()+6*std::mem::size_of::<crate::decoder::Snapshot>()+32769;
    let bound=paths.checked_add(conversions).and_then(|n|n.checked_add(fixed)).ok_or("header owner overflow")?;
    let ticket=e.reserve_preparation_feature(bound).map_err(|e| e.to_string())?;
    let mut scratch=Vec::new();scratch.try_reserve_exact(32769).map_err(|e|e.to_string())?;if scratch.capacity()!=32769{return Err("metric scratch capacity mismatch".into());}scratch.resize(32769,0);
    let mut staged:[Option<PathBuf>;4]=std::array::from_fn(|_|None);
    for(i,ch)in plan.channels.iter().enumerate(){let p=directory.join(format!("channel-{i:02}.{}",if ch.codec=="gzip"{"fq.gz"}else{"fq"}));if p.capacity()>2*(directory.capacity()+128){return Err("header staging capacity mismatch".into());}staged[i]=Some(p);}
    e.enable_dedup_backends();
    Ok(Self{staged,scratch,metrics:Metrics{enabled:plan.common.metrics,wall:None,cpu:None,rss:None},execution:e.clone(),_ticket:ticket})
 }
 pub(crate) fn observe(&mut self,started:Instant,cpu_start:Option<f64>){
    if self.metrics.enabled{
      self.metrics.cpu=crate::native_runtime::process_cpu_seconds().zip(cpu_start).map(|(a,b)|(a-b).max(0.0));self.metrics.wall=Some(started.elapsed().as_secs_f64());
      if let Ok(mut f)=File::open("/proc/self/status"){let mut n=0;while n<self.scratch.len(){match f.read(&mut self.scratch[n..]){Ok(0)=>break,Ok(v)=>n+=v,Err(_)=>{n=self.scratch.len();break;}}}if n<self.scratch.len(){self.metrics.rss=std::str::from_utf8(&self.scratch[..n]).ok().and_then(|s|s.lines().find_map(|l|l.strip_prefix("VmHWM:").and_then(|s|s.split_whitespace().next()).and_then(|s|s.parse::<u64>().ok()).and_then(|v|v.checked_mul(1024))));}}
    }

 }
}
impl Drop for Working{fn drop(&mut self){self.execution.clear_dedup_backends();}}
