pub(crate) fn typed_encode(header:&Header<'_>,state:&State,channels:&[Channel],e:&Arc<crate::native_execution::Execution>,views:&Views<'_>,site:u8)->Result<(String,crate::native_execution::FeatureTicket),String>{let doc=TypedDocument{header,state,channels,snapshot:false,views};let mut count=Count(0);serde_json::to_writer(&mut count,&doc).map_err(|e|e.to_string())?;let cap=count.0.checked_add(4096).ok_or("report size overflow")?;let ticket=crate::dedup_app::report_ticket(e,cap,site)?;let mut data=Vec::new();data.try_reserve_exact(cap).map_err(|e|e.to_string())?;if data.capacity()!=cap{return Err("report capacity mismatch".into());}serde_json::to_writer(Fixed{data:&mut data,limit:cap},&doc).map_err(|e|e.to_string())?;Ok((String::from_utf8(data).map_err(|e|e.to_string())?,ticket))}

#[cfg(test)]mod r4_capacity {
 use super::*;use crate::job_api::*;use std::{collections::BTreeMap,sync::atomic::AtomicBool};
 #[test]fn typed_header_owners(){
  let root=crate::test_support::workspace("r4").join("header-owners");std::fs::create_dir(&root).unwrap();let e=crate::native_execution::Execution::with_statistics_budget(1,1,Arc::new(AtomicBool::new(false)),None,crate::dedup_runtime::Runtime::statistics_bound(4).unwrap()).unwrap();let caller=e.reserve_preparation_feature(32<<20).unwrap();
  let mut rows=Vec::new();
  for enabled in [true,false]{
    let directory=root.join(if enabled{"on"}else{"off"});std::fs::create_dir(&directory).unwrap();
    let spec=JobSpec{layout:Layout::SplitPe,lanes:(0..128).map(|i|LaneDecl{id:format!("L{i}-<雪\\\""),inputs:(1..=2).map(|mate|InputDecl{channel:format!("R{mate}"),location:Location::Handle(format!("reader-{i}-{mate}")),format:Format::Fastq,phred:33,seekable:false}).collect()}).collect(),outputs:["R1","R2","duplicates1","duplicates2"].into_iter().enumerate().map(|(i,k)|OutputDecl{channel:k.into(),location:Location::Path(directory.join(format!("channel{i}.fastq"))),format:Format::Fastq,phred:33}).collect(),configured:BTreeMap::new(),supplied:BTreeMap::from([("spill-dir".into(),Setting::Text(directory.join("spill").to_string_lossy().into_owned())),("sample-id".into(),Setting::Text("<&雪\\\"".repeat(4096))),("threads".into(),Setting::Int(1)),("metrics".into(),Setting::Bool(enabled))]),json_report:Some(directory.join("report.json"))};
    let plan=crate::dedup_app::compile_api(&spec).unwrap();let meta=crate::job_api::metadata_bound(&spec).unwrap()*8;let ticket=e.reserve_preparation_feature(meta).unwrap();let inputs=spec.lanes.iter().flat_map(|l|l.inputs.iter()).map(|d|{let Location::Handle(h)=&d.location else{unreachable!()};(h.clone(),InputHandle::Stream(Box::new(std::io::empty())as Box<dyn Read+Send>))}).collect();let io=Arc::new(crate::native_io::OwnedIo::new(spec.clone(),JobIo{inputs,outputs:BTreeMap::new()},CancellationToken::default(),e.clone(),Arc::new(AtomicBool::new(false)),ticket));
    let mut emergency=super::super::Emergency::new(&e).unwrap();let mut publication=crate::dedup_publication::Publication::new(plan.spec.json_report.as_ref().unwrap(),&e).unwrap();let mut working=Working::new(&plan,&directory,&e,Some(&io)).unwrap();let scratch_cap=working.scratch.capacity();let scratch_ptr=working.scratch.as_ptr();working.observe(Instant::now(),crate::native_runtime::process_cpu_seconds());assert_eq!(working.scratch.capacity(),scratch_cap);assert_eq!(working.scratch.as_ptr(),scratch_ptr);assert_eq!(working.metrics.enabled,enabled);if !enabled{assert!(working.metrics.wall.is_none()&&working.metrics.cpu.is_none()&&working.metrics.rss.is_none());}
    e.record_dedup_runtime(crate::cpu_budget::CpuBudget::new(1),crate::decoder::Snapshot{lanes:[Some(crate::decoder::Decoder{backend:"plain",parallelism:0,active:None,rapid:false});2],current:Some(127),scope:""});
    let runtime=crate::dedup_runtime::Runtime::new(&directory,&plan.channels,&e).unwrap();let mut state=runtime.state.lock().unwrap();state.representatives=Some(0);state.duplicates=Some(0);let message="<&雪\\\"".repeat(2048);let h=Header{plan:&plan,working:&working,outputs:[Some(Output{owned:false,failed:true,bytes:Some(0)});4],message:Some(&message),stage:Some("input"),late:None,code:3,core:None,cleanup_stage:Some("internal-file"),publication:None,execution:&e};let views=Views::new(&plan.spec,&io,1,true,plan.catalogue.as_ref());
    let(text,out)=typed_encode(&h,&state,&plan.channels,&e,&views,2).unwrap();assert_eq!(text.capacity(),out.reserved_bytes());let v:Value=serde_json::from_str(&text).unwrap();assert!(v["identity"]["binary_sha256"].is_null());assert_eq!(v["identity"]["binary_sha256_unavailable_reason"],HASH_UNAVAILABLE);assert_eq!(v["run"]["sample_id"],plan.common.sample_id);assert_eq!(v["settings"]["effective"]["input_declarations"].as_array().unwrap().len(),128);assert_eq!(v["api"]["decoder_capabilities"]["bindings"].as_array().unwrap().len(),128);assert_eq!(v["execution"]["decoders"]["current_lane_id"],spec.lanes[127].id);assert_eq!(v["outputs"].as_array().unwrap().len(),4);assert_eq!(v["error"]["message"],message);assert_eq!(v["cleanup_stage"],"internal-file");assert_eq!(v["measurements"]["enabled"],enabled);assert!(v["execution"]["memory_budget"]["current_feature_reserved_bytes"].as_u64().unwrap()>=out.reserved_bytes()as u64+working._ticket.reserved_bytes()as u64+emergency._ticket.reserved_bytes()as u64);
    rows.push(serde_json::json!({"metrics":enabled,"working_reservation":working._ticket.reserved_bytes(),"header_struct":std::mem::size_of::<Header>(),"working_struct":std::mem::size_of::<Working>(),"backend_snapshot":std::mem::size_of::<crate::decoder::Snapshot>(),"staged_capacity_sum":working.staged.iter().flatten().map(PathBuf::capacity).sum::<usize>(),"platform_scratch":working.scratch.capacity(),"report_capacity":text.capacity(),"scope":"native serializer owner fixture; no sequencing processing or real decoder opening claimed"}));
    std::fs::write(directory.join("generated.json"),&text).unwrap();drop(v);drop(text);drop(out);drop(h);drop(views);drop(state);drop(runtime);drop(working);drop(publication);drop(emergency);drop(io);assert_eq!(e.facts()["memory_budget"]["current_feature_reserved_bytes"],32<<20);
  }
  std::fs::write(root.join("receipt.json"),serde_json::to_string_pretty(&rows).unwrap()).unwrap();drop(caller);assert_eq!(e.facts()["memory_budget"]["current_feature_reserved_bytes"],0);
 }
}
